// Единственная точка входа контент-бота. Личный бот: всё не от владельца — игнор.
// Собираем сообщение (мем-файл + сценарий в подписи) ИЛИ нажатие инлайн-кнопки апрува.
const OWNER = 648226895;
const cq = $json.callback_query;
if (cq) {
  if (cq.from?.id !== OWNER) return [];
  const [act, id] = (cq.data || '').split(':');
  return [{ json: {
    kind: act === 'ok' ? 'approve' : 'reject',
    script_id: Number(id), chat_id: cq.from.id, callback_query_id: cq.id,
  }}];
}
const m = $json.message || {};
if (m.from?.id !== OWNER) return [];
let file_id = null, file_kind = null;
if (m.video) { file_id = m.video.file_id; file_kind = 'clip'; }
else if (m.animation) { file_id = m.animation.file_id; file_kind = 'clip'; }
else if (m.document && (m.document.mime_type || '').startsWith('video')) { file_id = m.document.file_id; file_kind = 'clip'; }
else if (m.photo) { file_id = m.photo[m.photo.length - 1].file_id; file_kind = 'image'; }
const scenario = (m.caption || m.text || '').trim();
if (file_id && scenario) return [{ json: { kind: 'new', chat_id: m.from.id, file_id, file_kind, scenario } }];
return [{ json: { kind: 'help', chat_id: m.from.id,
  text: 'Пришли мем-видео (или картинку) с подписью-сценарием одним сообщением — соберу ролик.' } }];

// Скачанный мем лежит в binary. ВАЖНО: при binaryDataMode=filesystem поле
// binary[key].data пустое (байты на диске) — базу64 достаём через хелпер, он
// работает в любом режиме.
const item = $input.first();
const bin = item.binary || {};
const key = Object.keys(bin)[0];
if (!key) throw new Error('Download Meme не вернул бинарь — проверь fileId и что прислано видео/фото');
const buffer = await this.helpers.getBinaryDataBuffer(0, key);
const r = $('Route').first().json;
return [{ json: {
  scenario: r.scenario, file_kind: r.file_kind, chat_id: r.chat_id,
  meme_b64: buffer.toString('base64'),
}}];

// Достаём текст ответа LLM. openAi v2.3 отдаёт Responses-формат:
// { output: [ { content: [ { type:'output_text', text:'...' } ] } ] } — берём его
// первым, плюс запасные пути под другие форматы ноды.
function extractText(j) {
  if (Array.isArray(j.output)) {
    for (const o of j.output) {
      const part = Array.isArray(o.content) && o.content.find(c => c.text);
      if (part?.text) return part.text;
    }
  }
  if (Array.isArray(j.content)) {
    const part = j.content.find(c => c.text);
    if (part?.text) return part.text;
  }
  return j.message?.content ?? j.content ?? j.text ?? j.choices?.[0]?.message?.content ?? '';
}
const raw = extractText($json);
let s = String(raw).trim().replace(/^```(json)?/i, '').replace(/```$/,'').trim();
let obj;
try { obj = JSON.parse(s); }
catch (e) { throw new Error('LLM вернул не-JSON: ' + s.slice(0, 300)); }

const meme = $('Meme To Base64').item.json;
// Подставляем base64 мема в сегмент {meme:true} и приводим тип к реальному (clip/image).
const timeline = (obj.timeline || []).map(seg => {
  if (seg.meme) return { type: meme.file_kind === 'image' ? 'image' : 'clip',
                         data: meme.meme_b64, keep_audio: true,
                         ...(meme.file_kind === 'image' ? { duration: seg.duration || 3 } : {}) };
  return seg;
});
// Человекочитаемое превью таймлайна (без JSON: никаких _ < [ , ломающих парсер TG).
const summary = timeline.map((s, i) => {
  const n = i + 1;
  if (s.type === 'card')  return `${n}. плашка: "${s.text || ''}" (${s.duration || '?'}с)`;
  if (s.type === 'clip')  return `${n}. мем-видео`;
  if (s.type === 'image') return `${n}. мем-картинка (${s.duration || '?'}с)`;
  if (s.type === 'ai')    return `${n}. AI-клип`;
  return `${n}. ${s.type}`;
}).join('\n');
// Экранируем HTML-спецсимволы — сообщение уйдёт с parse_mode HTML.
const esc = t => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const msg = `<b>Хук:</b> ${esc(obj.hook || '')}\n<b>Caption:</b> ${esc(obj.caption || '')}\n\n<b>Таймлайн:</b>\n${esc(summary)}`;
return [{ json: {
  chat_id: meme.chat_id,
  hook: obj.hook || '', caption: obj.caption || '', hashtags: obj.hashtags || '', theme: obj.theme || '',
  timeline, msg,
}}];

parameters.query:
INSERT INTO reels_scripts (origin, hook, timeline, caption, hashtags, theme, status)
VALUES ('manual', $1, $2::jsonb, $3, $4, $5, 'scripted')
RETURNING id;

