// Один item на каждый ai-сегмент. Внешность Рыжа ЗАШИТА тут (залоченный вид) —
// LLM даёт лишь line/action, а полный промт для Veo собираем сами → Рыж одинаков
// во всех клипах. duration -> enum fal 4s/6s/8s.
const RYZH = "Vertical 9:16 2D flat cartoon animation. Anthropomorphic athletic bipedal fox mascot Ryzh: orange fur (#E8763A), cream muzzle and belly (#F7E4CF), big expressive eyes, pointy ears, fluffy tail with white tip, fit athletic build, wearing an orange sport headband (#FF7A30). Style: thick clean black outlines, soft cel shading, rounded friendly shapes, vibrant. Sly friendly fitness-mentor vibe.";
const tl = $json.timeline || [];
const jobs = [];
tl.forEach((s, i) => {
  if (s.type !== 'ai') return;
  const d = Math.round(Number(s.duration) || 8);
  const action = s.action ? (s.action.trim().replace(/\.?$/, '. ')) : '';
  const line = s.line ? ('He speaks in Russian, lip-synced: «' + s.line + '». Audio: playful upbeat male voice saying the line, no music.') : '';
  const prompt = s.prompt || (RYZH + ' ' + action + line).trim();
  jobs.push({ json: { seg_index: i, prompt, duration: d <= 4 ? '4s' : d <= 6 ? '6s' : '8s' } });
});
return jobs;

// Возвращаем url сгенерённых клипов в таймлайн по seg_index (порядок сохранён), чистим prompt.
const base = JSON.parse(JSON.stringify($('Load Script').first().json.timeline || []));
const jobs = $('Prep AI Jobs').all();
const gens = $input.all();
gens.forEach((g, k) => {
  const idx = jobs[k]?.json?.seg_index;
  const url = g.json?.video?.url;
  if (url != null && idx != null && base[idx]) {
    base[idx] = { ...base[idx], url };
    delete base[idx].prompt;
  }
});
return [{ json: { timeline: base } }];
